cd "$TMPDIR" && cat > week.json <<'EOF'
{
  "week_role": "base",
  "today": "2026-11-01",
  "history_weeks": [
    {"week_start": "2026-10-05", "minutes": 180, "km": 30, "long_min": 85},
    {"week_start": "2026-10-12", "minutes": 185, "km": 31, "long_min": 88},
    {"week_start": "2026-10-19", "minutes": 175, "km": 29, "long_min": 80},
    {"week_start": "2026-10-26", "minutes": 180, "km": 30, "long_min": 85}
  ],
  "history": [{"date": "2026-10-17", "minutes": 88, "km": 14, "type": "long"}],
  "plan": [
    {"date": "2026-11-03", "type": "strides", "minutes": 42, "km": 6.5, "title": "Easy + 6 strides"},
    {"date": "2026-11-05", "type": "threshold", "minutes": 52, "km": 9, "quality_minutes": 24, "title": "Cruise intervals 3 x 8 min"},
    {"date": "2026-11-07", "type": "easy", "minutes": 32, "km": 5, "title": "Easy"},
    {"date": "2026-11-08", "type": "long", "minutes": 95, "km": 15, "title": "Long run 15 km"}
  ]
}
EOF
python3 /Users/tomasstankovic/Development/running-coach/skills/running-coach/scripts/check_week.py week.json 2>&1 | grep -v -e xcrun -e xcodebuild

cd $TMPDIR/rc && python3 - <<'EOF'
import json
w=json.load(open("week.json"))
for p in w["plan"]:
    if p["date"]=="2026-11-03": p.update(minutes=35,km=5.5)
    if p["date"]=="2026-11-07": p.update(minutes=25,km=4)
json.dump(w,open("week.json","w"),indent=1)
EOF
python3 /Users/tomasstankovic/Development/running-coach/skills/running-coach/scripts/check_week.py week.json 2>&1 | grep -v "xcrun\|DVT"
python3 /Users/tomasstankovic/Development/running-coach/skills/running-coach/scripts/paces.py convert --threshold-pace 4:55 5:00-5:10 6:10-6:50 2>&1 | grep -v "xcrun\|DVT"
